function keepPersonaGrowth(){if(!isTargetRun()||!currentGrowthInstanceId)return;completeTargetGrowth('KEEP',null)}
function buildTargetReport(){const metrics=globalThis.runController.getRunMetrics(),runtimeState=personaRuntime.getState(),battleNodes=currentBattleNodeSequence(),last=metrics.battleScores.at(-1),finalBattleNode=battleNodes.find(node=>node.finalBattle)||battleNodes.at(-1),completed=last?.nodeId===finalBattleNode?.id&&last.win;metrics.totalRunDurationMs=Math.max(0,Date.now()-globalThis.runController.getState().runStartedAt);globalThis.runController.updateRunMetrics(metrics);globalThis.runController.updateRunResult({completed,finalNodeId:last?.nodeId||null});$('#target-report-summary').innerHTML=`<article><small>通关状态</small><strong>${completed?'已通关':'未通关'}</strong></article><article><small>累计得分</small><strong>${metrics.runTotalScore}</strong></article><article><small>最高单手</small><strong>${metrics.maxSingleHandScore}</strong></article><article><small>用时</small><strong>${Math.round(metrics.totalRunDurationMs/1000)} 秒</strong></article>`;$('#target-report-battles').innerHTML=battleNodes.map((node,index)=>{const item=metrics.battleScores.find(entry=>entry.nodeId===node.id);return`<article><b>战斗 ${String(index+1).padStart(2,'0')}</b><span>${item?`${item.score} / ${item.targetScore} · ${item.win?'胜':'败'}`:'未进入'}</span></article>`}).join('');$('#target-report-personas').innerHTML=runtimeState.runPersonaPool.map(id=>{const instance=runtimeState.personaInstancesById[id],template=instance&&personaRuntime.getTemplate(instance.templateId),triggers=metrics.personaTriggersByInstance[id]||0;return`<article><b>${template?.name||'未命名人格'}</b><small>${runtimeState.equippedPersonaInstanceIds.includes(id)?'当前装备':'未装备'} · 触发 ${triggers} 次</small></article>`}).join('')}
function openTargetReport(persist=true){window.showBattleFromRoute?.();buildTargetReport();if(!$('#target-report-dialog').open)$('#target-report-dialog').showModal();if(persist)window.commitRunSave?.('target_report','target_report_opened')}
function confirmTargetReport(){$('#target-report-dialog').close();globalThis.runController.completeNode({type:'TARGET_REPORT_COMPLETED',nodeId:'TARGET_RUN_REPORT'})}
function renderTargetCarry(){const metrics=globalThis.runController.getRunMetrics(),state=personaRuntime.getState(),ids=metrics.generatedPersonaInstanceIds.filter(id=>state.personaInstancesById[id]);$('#target-carry-options').innerHTML=ids.map(id=>{const instance=state.personaInstancesById[id],template=personaRuntime.getTemplate(instance.templateId),nodeLabel=/^N\d+$/.test(instance.generatedAtNodeId||'')?`节点 ${instance.generatedAtNodeId.slice(1)}`:'成长节点';return`<button data-carry-instance="${id}" class="${targetCarrySelectionId===id?'selected':''}"><h3>${template.name}</h3><small>${nodeLabel} · 永久收藏主效果</small><p>${targetEffectCopy(template)}</p></button>`}).join('')||'<p>本局在失败前没有生成人格，允许直接结束。</p>';$('#target-carry-note').textContent=ids.length?`已生成 ${ids.length} 张；只能永久带出其中 1 张，第二、第三属性不会保留。`:'没有可带出的人格。';$('#target-carry-confirm').disabled=ids.length>0&&!ids.includes(targetCarrySelectionId);$('#target-carry-confirm').textContent=ids.length?'确认永久带出并结束本局':'结束本局';document.querySelectorAll('[data-carry-instance]').forEach(button=>button.onclick=()=>{targetCarrySelectionId=button.dataset.carryInstance;globalThis.runController.setNodeRuntime({selectedPersonaInstanceId:targetCarrySelectionId});renderTargetCarry()})}
function openTargetCarry(persist=true){const runtime=globalThis.runController.getCurrentRuntime()?.data||{};targetCarrySelectionId=runtime.selectedPersonaInstanceId||null;renderTargetCarry();if(!$('#target-carry-dialog').open)$('#target-carry-dialog').showModal();if(persist)window.commitRunSave?.('target_carry','target_carry_opened')}
function confirmTargetCarry(){const metrics=globalThis.runController.getRunMetrics(),validIds=metrics.generatedPersonaInstanceIds;if(validIds.length&&!validIds.includes(targetCarrySelectionId))return;let collectionRecord=null;if(targetCarrySelectionId){const state=personaRuntime.getState(),instance=state.personaInstancesById[targetCarrySelectionId],template=instance&&personaRuntime.getTemplate(instance.templateId),saved=personaCollection.carryOut({instance,template,runTemplateId:currentRunTemplate().id,nodeId:'TARGET_PERSONA_CARRY_OUT'});if(!saved.ok){$('#target-carry-note').textContent='永久收藏保存失败，请保留当前页面并重试。';return}collectionRecord=saved.record;syncPermanentPersonaPool()}globalThis.runController.updateRunResult({selectedCarryOutPersonaInstanceId:targetCarrySelectionId,permanentCollectionCardId:collectionRecord?.cardId||null});targetRawEvent('PERSONA_CARRY_OUT',{instanceId:targetCarrySelectionId,collectionCardId:collectionRecord?.cardId||null});$('#target-carry-dialog').close();globalThis.runController.completeNode({type:'PERSONA_CARRY_OUT_COMPLETED',nodeId:'TARGET_PERSONA_CARRY_OUT',instanceId:targetCarrySelectionId,collectionCardId:collectionRecord?.cardId||null})}
